/** HTTP transport and serving for graphs generated by the web launcher. */

import type { IncomingMessage, ServerResponse } from "node:http";
import { CliError } from "../errors";
import { sendHtml, sendJson, sendJsonFile } from "./http-response";
import { telemetrySourceDescriptors } from "./overlay-source";
import { SyntheticExecutionError } from "./synthetic-error";
import { githubTokenFor } from "./web-auth";
import { injectViewBoot, syntheticExecutionBootCapability } from "./web-boot";
import { WebError } from "./web-error";
import {
  isOperationCancelled,
  requestCancellation,
  responseCanWrite,
} from "./web-cancellation";
import { WebGraphViewLeaseError } from "./web-graph-store";
import { PrReviewHandoffClaimError } from "./web-pr-review-handoff";
import { generateGraph } from "./web-generation";
import { parseGenerateRequest, readJsonBody } from "./web-request";
import type { Context } from "./web-server";
import { streamedOverloadLine } from "./web-overload";
import { isWebServiceShutdown, WEB_SERVICE_SHUTDOWN_MESSAGE } from "./web-service-shutdown";

export async function handleGenerate(ctx: Context, request: IncomingMessage, response: ServerResponse): Promise<void> {
  if (acceptsNdjson(request)) {
    await handleGenerateStream(ctx, request, response);
    return;
  }
  const cancellation = requestCancellation(request, response, ctx.shutdownSignal);
  try {
    const parsed = parseGenerateRequest(await readJsonBody(request, cancellation.signal));
    const result = await generateGraph(
      ctx,
      parsed,
      githubTokenFor(ctx, request, parsed.token),
      undefined,
      cancellation.signal,
    );
    if (responseCanWrite(response)) sendJson(response, 200, result);
  } finally {
    cancellation.dispose();
  }
}

async function handleGenerateStream(ctx: Context, request: IncomingMessage, response: ServerResponse): Promise<void> {
  const cancellation = requestCancellation(request, response, ctx.shutdownSignal);
  beginNdjson(response);
  try {
    const parsed = parseGenerateRequest(await readJsonBody(request, cancellation.signal));
    const result = await generateGraph(ctx, parsed, githubTokenFor(ctx, request, parsed.token), (stage) =>
      writeLine(response, { stage }),
      cancellation.signal,
    );
    await writeLine(response, { stage: "done", ...result });
  } catch (error) {
    if (!isOperationCancelled(error) && responseCanWrite(response)) {
      await writeLine(
        response,
        streamedOverloadLine(error) ?? { stage: "error", message: safeGenerateMessage(error) },
      );
    }
  } finally {
    cancellation.dispose();
    if (responseCanWrite(response)) response.end();
  }
}

function acceptsNdjson(request: IncomingMessage): boolean {
  const accept = request.headers.accept;
  const value = Array.isArray(accept) ? accept.join(",") : (accept ?? "");
  return value
    .split(",")
    .some((part: string) => part.trim().split(";", 1)[0]?.toLowerCase() === "application/x-ndjson");
}

function beginNdjson(response: ServerResponse): void {
  response.writeHead(200, { "content-type": "application/x-ndjson; charset=utf-8", "cache-control": "no-cache" });
}

/** Resolve once Node has handed the line off, yielding before CPU-heavy extraction begins. */
function writeLine(response: ServerResponse, line: Record<string, unknown>): Promise<void> {
  if (!responseCanWrite(response)) return Promise.resolve();
  return new Promise((resolve, reject) => {
    response.write(`${JSON.stringify(line)}\n`, (error) => {
      if (error) {
        reject(error);
        return;
      }
      resolve();
    });
  });
}

function safeGenerateMessage(error: unknown): string {
  if (isWebServiceShutdown(error)) return WEB_SERVICE_SHUTDOWN_MESSAGE;
  if (error instanceof SyntheticExecutionError || error instanceof WebError || error instanceof CliError) {
    return error.message;
  }
  return "internal error while generating the blueprint";
}

export async function sendGraph(ctx: Context, response: ServerResponse, id: string | null): Promise<void> {
  const registration = id ? ctx.graphStore.acquire(id) : undefined;
  if (registration === undefined) {
    sendJson(response, 404, { error: "unknown graph id" });
    return;
  }
  try {
    if (registration.descriptor.rawGraphPayload !== "complete") {
      sendJson(response, 409, {
        error: "raw graph payload is unavailable for a projection-only graph",
      });
      return;
    }
    await sendJsonFile(response, registration.artifactPath);
  } finally {
    registration.release();
  }
}

export function sendMeta(ctx: Context, response: ServerResponse, id: string | null): void {
  const registration = id ? ctx.graphStore.acquire(id) : undefined;
  if (registration === undefined) {
    sendJson(response, 404, { error: "unknown graph id" });
    return;
  }
  try {
    const descriptor = registration.descriptor;
    const graphId = id as string;
    sendJson(response, 200, {
      schemaVersion: descriptor.summary.schemaVersion,
      generatedAt: descriptor.summary.generatedAt,
      nodeCount: descriptor.summary.nodeCount,
      hasOverlay: false,
      environments: [],
      telemetrySources: telemetrySourceDescriptors({ kind: "none" }),
      ...syntheticExecutionBootCapability(
        graphId,
        descriptor.source,
        descriptor.synthetic.scenarios,
        descriptor.synthetic.trust,
      ),
    });
  } finally {
    registration.release();
  }
}

export function sendView(ctx: Context, response: ServerResponse, url: URL): void {
  const ids = url.searchParams.getAll("id");
  const handoffIds = url.searchParams.getAll("handoff");
  if (handoffIds.length > 1 || (handoffIds.length === 1 && ids.length !== 1)) {
    sendHtml(
      response,
      "<!doctype html><meta charset=utf-8><title>Meridian</title><p>Invalid prepared review URL.</p>",
      400,
      { "cache-control": "no-store", "referrer-policy": "no-referrer" },
    );
    return;
  }
  const id = ids[0] ?? null;
  let handoff: ReturnType<Context["prReviewHandoffs"]["inspectClaim"]> | null = null;
  if (handoffIds.length === 1) {
    try {
      handoff = ctx.prReviewHandoffs.inspectClaim(handoffIds[0]!);
    } catch (error) {
      if (!(error instanceof PrReviewHandoffClaimError)) throw error;
      sendHtml(
        response,
        "<!doctype html><meta charset=utf-8><title>Meridian</title><p>This prepared review link has expired. Return to the pull request picker and try again.</p>",
        410,
        { "cache-control": "no-store", "referrer-policy": "no-referrer" },
      );
      return;
    }
    if (id !== handoff.pair.headGraphId) {
      sendHtml(
        response,
        "<!doctype html><meta charset=utf-8><title>Meridian</title><p>The prepared review link does not match this graph.</p>",
        409,
        { "cache-control": "no-store", "referrer-policy": "no-referrer" },
      );
      return;
    }
  }
  const registration = id ? ctx.graphStore.acquire(id) : undefined;
  if (registration === undefined) {
    sendHtml(response, "<!doctype html><meta charset=utf-8><title>Meridian</title><p>Unknown graph id.</p>", 404);
    return;
  }
  let viewLeaseId: string | null = null;
  try {
    const descriptor = registration.descriptor;
    const graphId = id as string;
    const protectedGraphIds = handoff === null
      ? [graphId]
      : [handoff.pair.headGraphId, handoff.pair.comparisonGraphId];
    const grant = ctx.graphStore.createViewLease(graphId, protectedGraphIds);
    viewLeaseId = grant.leaseId;
    const attached = handoff === null
      ? null
      : ctx.prReviewHandoffs.attach(handoff.claimId, grant.leaseId);
    const canonicalUrl = new URL(url.pathname + url.search, "http://meridian.local");
    canonicalUrl.searchParams.delete("handoff");
    sendHtml(response, injectViewBoot(
      ctx.rendererIndex,
      graphId,
      descriptor.source,
      {
        version: 1,
        leaseId: grant.leaseId,
        url: `/api/graph-views/${grant.leaseId}`,
        createUrl: "/api/graph-views",
        graphIds: protectedGraphIds,
        expiresAtMs: grant.expiresAtMs,
        heartbeatIntervalMs: grant.heartbeatIntervalMs,
      },
      descriptor.synthetic.scenarios,
      descriptor.synthetic.trust,
      attached === null ? {} : {
        preparedReviewHandoff: {
          version: 1,
          claimId: attached.claimId,
          url: `/api/pr-review-handoffs/${attached.claimId}`,
          expiresAtMs: attached.expiresAtMs,
          headGraphId: attached.pair.headGraphId,
          comparisonGraphId: attached.pair.comparisonGraphId,
        },
        canonicalUrl: `${canonicalUrl.pathname}${canonicalUrl.search}`,
      },
    ), 200, { "cache-control": "no-store", "referrer-policy": "no-referrer" });
  } catch (error) {
    if (viewLeaseId !== null) ctx.graphStore.releaseViewLease(viewLeaseId);
    if (error instanceof PrReviewHandoffClaimError) {
      sendHtml(
        response,
        "<!doctype html><meta charset=utf-8><title>Meridian</title><p>This prepared review link is no longer available. Return to the pull request picker and try again.</p>",
        410,
        { "cache-control": "no-store", "referrer-policy": "no-referrer" },
      );
      return;
    }
    if (error instanceof WebGraphViewLeaseError && error.code === "capacity") {
      sendHtml(
        response,
        "<!doctype html><meta charset=utf-8><title>Meridian</title><p>Too many active graph views. Close an unused tab and retry.</p>",
        503,
      );
      return;
    }
    throw error;
  } finally {
    registration.release();
  }
}
